// ── paste n8n/code/slot_plan.js here ──
// Produces one item per posting slot for tomorrow, with jitter, skip probability,
// a forced non-commercial slot, and the breed/explore instruction from wf4.
const cfg = $json;
const settings = { posting: cfg.posting };
const plan = Array.isArray(cfg.next_cycle_plan) ? [...cfg.next_cycle_plan] : [];
const s = cfg.posting;
const dayStart = new Date(); dayStart.setHours(0,0,0,0); dayStart.setDate(dayStart.getDate()+1);
const slots = [];
const hours = s.slot_hours;
const freeIdx = Math.floor(Math.random()*hours.length);
for (let i=0;i<hours.length;i++){
  if (Math.random() < (s.skip_probability ?? 0.08)) continue;
  const jitter = Math.round((Math.random()*2-1)*(s.jitter_minutes ?? 18));
  const t = new Date(dayStart); t.setHours(hours[i],0,0,0); t.setMinutes(t.getMinutes()+jitter);
  t.setSeconds(Math.floor(Math.random()*60));
  slots.push({
    slot_index:i, scheduled_at:t.toISOString(),
    force_sell_intensity: i===freeIdx ? '0' : null,
    is_carousel: Math.random() < (s.carousel_probability ?? 0.4),
    reply_delay_sec: Math.round(s.reply_delay_range_sec[0] + Math.random()*(s.reply_delay_range_sec[1]-s.reply_delay_range_sec[0])),
    plan: plan.shift() ?? { mode:'explore' },
    cfg
  });
}
if (!slots.length){ const t=new Date(dayStart); t.setHours(19,12,0,0);
  slots.push({slot_index:3,scheduled_at:t.toISOString(),force_sell_intensity:null,is_carousel:false,reply_delay_sec:70,plan:{mode:'explore'},cfg}); }
return slots.map(x=>({json:x}));

